   Interação entre um bloco &finally; e exit chamado em um bloco &try;


<?php
try {
    echo 'quit';
    exit(0);
} finally {
    echo 'finally';
}


   &example.outputs;


quit

   Interação entre um bloco &finally; e exit chamado em um bloco &catch;


<?php
try {
    throw new Exception('foo');
} catch (Exception $e) {
    echo 'catch';
    exit(0);
} finally {
    echo 'finally ';
}


   &example.outputs;


catch

   Todos os blocos &finally; são ignorados quando exit é chamado


<?php
try {
    try {
        echo 'quit';
        exit(0);
    } finally {
        echo 'finally interno';
    }
} finally {
    echo 'finally externo';
}


   &example.outputs;


quit

   Ignorando um bloco &finally; externo ao chamar exit


<?php
try {
    try {
        echo 'try', "\n";
    } finally {
        echo 'finally interno';
        exit(0);
    }
} finally {
    echo 'finally externo';
}


   &example.outputs;


try
finally interno
